# Generated by dev/build_study.py from the hub's simulator, with its hidden processes left out (see
# tools/study/README.md). Edit freely: it is the team's copy.
"""The restoration simulator.

One scenario on the fixed grid, stepped every 30 simulated seconds for 16 hours. Each step every area's
controller sees its own area and sends commands; the simulator applies them with the physics a real
restoration fights:

- islands: buses connected by closed breakers to at least one running synchronous unit are live;
- frequency: each island's frequency follows the swing equation with governor droop (limited to each unit's
  primary reserve) and optional AGC, integrated in sub-steps, with under-frequency load shedding and collapse
  below 57.5 Hz;
- voltage: an AC power flow per island; overvoltage on lightly loaded lines trips them, a power flow that
  does not converge is a voltage collapse;
- energising dead network: line charging plus transformer inrush against the island's strength; closing
  onto a hidden fault trips at once and can collapse a weak island; relays that operate on inrush;
- joining islands: a synchro-check relay on every breaker; forcing a close out of phase damages
  equipment and voids the scenario;
- plants: hot, warm and cold start times from what each unit was doing before the blackout, cranking power,
  minimum load, energy-limited hydro and diesel, start failures drawn per attempt, units damaged in the trip,
  early-life trips after a restart, maintenance outages;
- protection: distance relays set too tight that trip on load until a crew corrects them;
- loads: cold load pickup amplified by the weather, priority feeders, under-frequency stages;
- substations: batteries that run out while dark, RTUs lost in the blackout, then breakers there need a crew;
- the channel between control rooms: credits per recipient, a one-minute delay, and one message per ten steps
  once an area's telecom node has been dark past its battery.

Score: the restoration index (mean over steps of the squared priority-weighted share of demand served) times the
penalties, divided by the scenario's capacity bound (bound.py), so 1.0 is the physical maximum.
"""
import hashlib
import math
import random

import numpy as np

from . import bound as BD
from . import equipment as EQ
from . import grid as G
from . import powerflow as PF
from . import scenario as SC

F0 = 60.0
SYNC_KINDS = ("hydro", "diesel", "ct", "ccgt", "coal", "nuclear")
RENEW = ("wind", "solar")
MAX_SWITCHING = 12          # switching operations per area per step
ENERGISE_INTERVAL_MIN = 5.0  # a control room energises dead network at most once per this many minutes (checks)
MAX_ACTIONS = 60
# The channel between control rooms: every recipient of a message costs one credit; an area earns MSG_REFILL credits a
# step and banks at most MSG_BANK; a message is delivered MSG_DELAY_STEPS steps after it is sent.
MSG_REFILL = 2
MSG_BANK = 20
MSG_DELAY_STEPS = 2
MAX_MESSAGE_CHARS = 600
SYNC_SLIP_HZ = 0.10
SYNC_DV = 0.05
SYNC_ANGLE = 10.0
LOOP_ANGLE = 25.0
UF_COLLAPSE = 57.5
OF_TRIP = 61.8
V_TRIP = 1.12
V_DAMAGE = 1.15
V_LOW = 0.88
PRIORITY_WEIGHT = 3.0
# Penalties multiply the restoration index, so partial restorations keep partial credit.
PEN_COLLAPSE = 0.95      # per island collapse that drops at least 100 MW of served load
PEN_NUCLEAR = 0.90       # per nuclear plant whose cooling backup ran out before off-site power returned
PEN_DAMAGE = 0.97        # per equipment-damage event (forced out-of-angle loop closure, overvoltage above 1.15 pu)
RTU_FIX_MIN = 30         # a crew restores a failed substation RTU after this long on site
FAULT_REPAIR_MIN = 240   # patrol, repair and test of a permanent line fault
SWITCH_REPAIR_MIN = 25   # a stuck breaker or a misset relay


def _u01(seed, *keys):
    """A uniform draw fixed by the scenario and the keys, independent of the order things happen in."""
    h = hashlib.sha256(":".join(str(k) for k in (seed,) + keys).encode()).digest()
    return int.from_bytes(h[:8], "big") / 2.0 ** 64


class Sim:
    def __init__(self, grid, scen, horizon_min=SC.HORIZON_MIN):
        """horizon_min: where the run stops (a practice drill may stop early; the controllers still see the
        scenario's full horizon)."""
        self.g, self.s = grid, scen
        self.horizon = min(float(horizon_min), SC.HORIZON_MIN)
        B, L, U, LD = grid["buses"], grid["branches"], grid["units"], grid["loads"]
        self.nb, self.nl, self.nu, self.nf = len(B), len(L), len(U), len(LD)
        self.priv = [G.area_private(grid, a) for a in range(G.N_AREAS)]
        self.step_i = 0
        self.t = 0.0                                  # minutes since the blackout
        self.bus_id = [b["id"] for b in B]
        self.bus_area = np.array([b["area"] for b in B])
        self.idx = {b["id"]: i for i, b in enumerate(B)}
        self.br_idx = {b["id"]: i for i, b in enumerate(L)}
        self.u_idx = {u["id"]: i for i, u in enumerate(U)}
        self.f_idx = {l["id"]: i for i, l in enumerate(LD)}
        self.sh_idx = {s["id"]: i for i, s in enumerate(grid["shunts"])}
        self.bf = np.array([b["f"] for b in L]); self.bt = np.array([b["t"] for b in L])
        self.br_r = np.array([b["r"] for b in L]); self.br_x = np.array([b["x"] for b in L])
        self.br_b = np.array([b["b"] for b in L]); self.br_rating = np.array([b["rating"] for b in L]) * scen["line_rating_factor"]
        self.br_tie = np.array([b["tie"] for b in L])
        self.br_owner = [self._owners(b) for b in L]
        self.bus_branches = [[] for _ in B]
        for k, b in enumerate(L):
            self.bus_branches[b["f"]].append(k); self.bus_branches[b["t"]].append(k)
        # breakers
        self.closed = np.ones(self.nl, bool)
        self.closed[scen["open_at_start"]] = False
        self.faulted = set(scen["faulted"])
        self.closed[list(self.faulted)] = False       # a faulted line tripped during the collapse
        self.fault_known = set()
        self.stuck = set(scen["stuck"])
        self.stuck_known = set()
        self.relay_misop = {int(k): v for k, v in scen["relay_misop"].items()}
        self.energise_tries = np.zeros(self.nl, int)
        self.scada_lost = set(scen["scada_lost"])
        self.overload_count = np.zeros(self.nl, int)
        # units
        self.u_kind = [u["kind"] for u in U]
        self.u_bus = np.array([u["bus"] for u in U]); self.u_area = np.array([u["area"] for u in U])
        self.u_pmax = np.array([u["pmax"] for u in U], float); self.u_pmin = np.array([u["pmin"] for u in U], float)
        self.u_H = np.array([u["H"] for u in U], float); self.u_Tg = np.array([u["Tg"] for u in U], float)
        self.u_ramp = np.array([u["ramp_mw_min"] for u in U], float)
        self.u_sync = np.array([k in SYNC_KINDS for k in self.u_kind])
        self.state = ["unavailable" if i in scen["unavailable"] else "off" for i in range(self.nu)]
        self.pm = np.zeros(self.nu); self.pset = np.zeros(self.nu); self.ptarget = np.zeros(self.nu)
        self.qg = np.zeros(self.nu)
        self.vset = np.full(self.nu, 1.0)
        self.agc = np.zeros(self.nu, bool)
        self.agc_hz = np.full(self.nu, F0)
        self.start_end = np.zeros(self.nu)
        # minute it last stopped: the blackout for units that were running, earlier for those that were off
        self.last_off = np.array([-60.0 * scen["offline_h"].get(i, 0.0) for i in range(self.nu)])
        self.lock_until = np.zeros(self.nu)
        self.last_energise = np.full(G.N_AREAS, -1e9)   # minute each area last energised dead network
        self.start_fail = {int(i): list(v) for i, v in scen["start_fail"].items()}
        self.attempts = np.zeros(self.nu, int)
        self.damaged = set(scen["damaged"])
        self.early_trip = {int(i): m for i, m in scen["early_trip"].items()}
        self.first_online = np.full(self.nu, -1.0)
        self.u_gov = np.array([u.get("gov_reserve", 0.0) for u in U], float)
        self.below_pmin = np.full(self.nu, -1.0)
        self.energy = np.array([u["energy_mwh"] if u["energy_mwh"] is not None else np.inf for u in U], float)
        self.renew_on = np.zeros(self.nu, bool)
        self.wind_scale = scen["wind"]
        # feeders
        self.fd_bus = np.array([l["bus"] for l in LD]); self.fd_area = np.array([l["area"] for l in LD])
        self.fd_mw = np.array([l["mw"] for l in LD], float)
        self.fd_w = np.array([PRIORITY_WEIGHT if l["priority"] else 1.0 for l in LD])
        self.fd_tan = np.array([l["pf_tan"] for l in LD])
        self.fd_stage = np.array([l["ufls_stage"] for l in LD])
        self.fd_on = np.zeros(self.nf, bool)
        self.fd_on[scen["feeders_closed"]] = True
        self.fd_served_since = np.full(self.nf, -1.0)  # minute power came back, -1 while dark
        self.fd_dark_since = np.zeros(self.nf)
        self.clpu_f = 1.0 + np.array([self.priv[a]["cold_load_pickup"]["factor"] - 1.0 for a in self.fd_area]) \
            * scen["cold_load_severity"]
        self.clpu_tau = np.array([self.priv[a]["cold_load_pickup"]["decay_min"] for a in self.fd_area])
        self.fd_peak = np.zeros(self.nf)              # cold load multiplier at the moment of pickup
        # shunts
        self.sh_bus = np.array([s["bus"] for s in grid["shunts"]]); self.sh_mvar = np.array([s["mvar"] for s in grid["shunts"]])
        self.sh_area = np.array([s["area"] for s in grid["shunts"]])
        self.sh_on = np.zeros(len(grid["shunts"]), bool)
        # buses
        self.island = np.full(self.nb, -1)
        self.f_bus = np.full(self.nb, np.nan)
        self.th_bus = np.zeros(self.nb)               # island phase reference (rad) carried by each live bus
        self.V = np.ones(self.nb, complex)
        self.dark_since = np.zeros(self.nb)
        self.battery_h = np.array(scen["battery_h"])
        self.telecom_bus = [G.N_AREAS and self.g["areas"][a]["first_bus"] for a in range(G.N_AREAS)]
        # crews
        self.crews = []
        for a in range(G.N_AREAS):
            for c in self.priv[a]["crews"]:
                self.crews.append(dict(id=c["id"], area=a, at=self.idx[c["depot"]], to=None, eta=0.0,
                                       kmh=c["kmh"] * scen["crew_speed"], task=None, task_end=0.0, task_target=None))
        self.crew_idx = {c["id"]: i for i, c in enumerate(self.crews)}
        # what each area owns, for observations
        self.area_buses = [np.flatnonzero(self.bus_area == a) for a in range(G.N_AREAS)]
        self.area_branches = [[k for k in range(self.nl) if a in self.br_owner[k]] for a in range(G.N_AREAS)]
        self.area_units = [[int(u) for u in np.flatnonzero(self.u_area == a)] for a in range(G.N_AREAS)]
        self.area_feeders = [[int(f) for f in np.flatnonzero(self.fd_area == a)] for a in range(G.N_AREAS)]
        self._draw_cache = (-1, None, None)
        self.fd_bus_set = set(self.fd_bus.tolist())
        self.u_bus_set = set(self.u_bus.tolist())
        self.start_begin = np.zeros(self.nu)
        self.online_since = np.zeros(self.nu)
        self.ov_count = np.zeros(self.nb, int)
        # bookkeeping
        self.events = [[] for _ in range(G.N_AREAS)]
        self.served_mwh = 0.0; self.demand_mwh = 0.0
        self.served_w = 0.0; self.demand_w = 0.0
        self.collapses = 0; self.nuclear_missed = []; self.damage = 0; self.out_of_phase = False
        self.nuclear_done = set()
        self.msg_credits = [float(MSG_REFILL)] * G.N_AREAS
        self.msg_budget_next = [0] * G.N_AREAS
        self.msg_queue = {}                           # step it is delivered at -> inboxes
        self.msg_allowed_obs = [(MSG_REFILL, False)] * G.N_AREAS
        self.share_sq = 0.0; self.n_steps = 0
        self.timeline = []
        self.need_pf = True
        self.since_pf = 0
        self.ev_i = 0
        self.rng = random.Random(scen["seed"] ^ 0x5EED)
        self.eq = EQ.Rules(self, grid.get("equipment") or {})
        self._components()

    # ------------------------------------------------------------------ helpers
    def _owners(self, b):
        B = self.g["buses"]
        return sorted({B[b["f"]]["area"], B[b["t"]]["area"]})

    def ev(self, areas, text):
        for a in (areas if isinstance(areas, (list, tuple, set)) else [areas]):
            self.events[a].append(f"[{self.t:6.1f} min] {text}")

    def _components(self):
        """Union-find over closed breakers; marks islands that contain a running synchronous unit as live."""
        parent = list(range(self.nb))

        def find(i):
            while parent[i] != i:
                parent[i] = parent[parent[i]]
                i = parent[i]
            return i

        for k in np.flatnonzero(self.closed):
            a, b = find(self.bf[k]), find(self.bt[k])
            if a != b:
                parent[a] = b
        roots = np.array([find(i) for i in range(self.nb)])
        live_roots = {}
        for u in range(self.nu):
            if self.state[u] == "online" and self.u_sync[u]:
                live_roots.setdefault(roots[self.u_bus[u]], []).append(u)
        old_f, old_th, old_island = self.f_bus.copy(), self.th_bus.copy(), self.island.copy()
        self.island[:] = -1
        newly = []
        for r, us in live_roots.items():
            members = np.flatnonzero(roots == r)
            big = max(us, key=lambda u: self.u_pmax[u])
            fb = old_f[self.u_bus[big]]
            th = old_th[self.u_bus[big]]
            if not np.isfinite(fb):
                fb, th = F0, 0.0
            label = int(self.u_bus[big])
            dead = members[old_island[members] < 0]
            newly.extend(dead.tolist())
            self.island[members] = label
            self.f_bus[members] = fb
            self.th_bus[members] = th
        dead = self.island < 0
        self.f_bus[dead] = np.nan
        went_dark = dead & (old_island >= 0)
        self.dark_since[went_dark] = self.t
        for i in newly:
            self.dark_since[i] = -1
        self.need_pf = True
        return newly

    def islands(self):
        out = {}
        for i in np.flatnonzero(self.island >= 0):
            out.setdefault(int(self.island[i]), []).append(i)
        return out

    def _island_units(self, label, sync_only=True):
        return [u for u in range(self.nu) if self.state[u] == "online" and self.island[self.u_bus[u]] == label
                and (self.u_sync[u] or not sync_only)]

    def _online_cap(self, label):
        return float(sum(self.u_pmax[u] for u in self._island_units(label)))

    def _remote_ok(self, bus, control=True):
        """Telemetry and remote control at a substation: live, or batteries still up, or a crew on site. A substation
        whose RTU failed has neither until a crew has fixed it, only local control while a crew is there. Local
        equipment can take remote control away where its substations have none (`control`: asked for control, not
        telemetry)."""
        if control:
            r = self.eq.remote_override(bus)
            if r is not None:
                return r
        if bus in self.scada_lost:
            return self._crew_at(bus)
        if self.island[bus] >= 0:
            return True
        if self.dark_since[bus] >= 0 and (self.t - self.dark_since[bus]) <= self.battery_h[bus] * 60:
            return True
        return any(c["at"] == bus and c["to"] is None for c in self.crews)

    def _crew_at(self, bus):
        return any(c["at"] == bus and c["to"] is None for c in self.crews)

    def _dead_section(self, start, extra_branch=None):
        """Dead buses reachable from `start` through closed breakers (plus one branch about to close)."""
        seen = {start}
        stack = [start]
        while stack:
            i = stack.pop()
            for k in self.bus_branches[i]:
                if not self.closed[k] and k != extra_branch:
                    continue
                j = self.bt[k] if self.bf[k] == i else self.bf[k]
                if j not in seen and self.island[j] < 0:
                    seen.add(j); stack.append(j)
        return seen

    def _inrush(self, section, area, skip_bus=None):
        """MVA a dead section asks for when it is energised: charging of its lines plus transformer inrush."""
        P = self.priv[area]
        sec = set(int(i) for i in section)
        ks = {k for i in sec for k in self.bus_branches[i] if self.closed[k] and self.bf[k] in sec and self.bt[k] in sec}
        charge = float(sum(self.br_b[k] for k in ks)) * G.BASE_MVA
        has_tx = sum(1 for i in sec if i != skip_bus and (i in self.fd_bus_set or i in self.u_bus_set))
        return charge + has_tx * P["transformer_inrush_mva"]

    # ------------------------------------------------------------------ collapse
    def collapse(self, label, why):
        members = np.flatnonzero(self.island == label)
        areas = sorted(set(self.bus_area[members].tolist()))
        served = float(sum(self.fd_mw[f] for f in range(self.nf) if self.fd_on[f] and self.island[self.fd_bus[f]] == label))
        for u in range(self.nu):
            if self.state[u] in ("online", "starting") and self.island[self.u_bus[u]] == label:
                self._stop_unit(u, trip=True)
        for f in range(self.nf):
            if self.island[self.fd_bus[f]] == label and self.fd_on[f]:
                self.fd_on[f] = False
        if served >= 100:
            self.collapses += 1
        self.ev(areas, f"ISLAND COLLAPSE ({len(members)} buses, {served:.0f} MW of load): {why}")
        self._components()

    def _stop_unit(self, u, trip=False):
        if self.state[u] in ("online", "starting"):
            self.last_off[u] = self.t
        self.state[u] = "off" if self.state[u] != "unavailable" else "unavailable"
        self.pm[u] = 0.0; self.pset[u] = 0.0; self.ptarget[u] = 0.0; self.agc[u] = False; self.qg[u] = 0.0
        self.below_pmin[u] = -1.0
        if trip:
            self.lock_until[u] = self.t + 10.0

    # ------------------------------------------------------------------ actions
    def apply(self, actions_by_area):
        """Apply every area's commands for this step. Returns nothing; results go into each area's events."""
        tie_close = {}
        plan = []
        for a, acts in enumerate(actions_by_area):
            if not isinstance(acts, list):
                continue
            switching = 0
            for act in acts[:MAX_ACTIONS]:
                if not isinstance(act, dict):
                    continue
                op = act.get("op")
                if op in ("close", "open", "start", "stop", "feeder", "shunt", "repair", "dispatch"):
                    switching += 1
                    if switching > MAX_SWITCHING:
                        self.ev(a, f"command ignored: more than {MAX_SWITCHING} switching operations this step")
                        continue
                plan.append((a, act))
        # The order MANUAL.md states. Dispatch runs last, so a crew sent on this step still counts as present for this
        # step's switching and repair at the substation it leaves.
        order = {"open": 0, "stop": 1, "set_p": 2, "agc": 2, "set_v": 2, "renewable": 2, "repair": 2, "equip": 2,
                 "start": 3, "close": 4, "shunt": 5, "feeder": 6, "dispatch": 7}
        plan.sort(key=lambda x: order.get(x[1].get("op"), 9))
        for a, act in plan:
            op = act.get("op")
            try:
                if op == "close":
                    k = self.br_idx.get(act.get("branch"))
                    if k is None or a not in self.br_owner[k]:
                        raise ValueError(f"close: {act.get('branch')} is not a breaker of your area")
                    if self.br_tie[k]:
                        tie_close.setdefault(k, {})[a] = bool(act.get("force"))
                        if len(tie_close[k]) < 2:
                            continue
                        force = any(tie_close[k].values())
                        self._close(k, a, force, both=self.br_owner[k])
                    else:
                        self._close(k, a, bool(act.get("force")), both=[a])
                elif op == "open":
                    k = self.br_idx.get(act.get("branch"))
                    if k is None or a not in self.br_owner[k]:
                        raise ValueError(f"open: {act.get('branch')} is not a breaker of your area")
                    if not (self._remote_ok(self.bf[k]) or self._remote_ok(self.bt[k])):
                        raise ValueError(f"open {act['branch']}: no remote control (substation batteries exhausted); send a crew")
                    if self.closed[k]:
                        self.closed[k] = False
                        self.ev(self.br_owner[k], f"{act['branch']} opened by {G.area_name(a)}")
                        self._components()
                elif op == "start":
                    self._start(a, act.get("unit"))
                elif op == "stop":
                    u = self._my_unit(a, act.get("unit"))
                    if self.state[u] in ("online", "starting"):
                        self._stop_unit(u)
                        self.ev(a, f"{act['unit']} stopped")
                        self._components()
                elif op == "set_p":
                    u = self._my_unit(a, act.get("unit"))
                    mw = float(act.get("mw"))
                    if not math.isfinite(mw):
                        raise ValueError("set_p: mw must be a number")
                    self.ptarget[u] = min(max(mw, 0.0), self.u_pmax[u])
                elif op == "agc":
                    u = self._my_unit(a, act.get("unit"))
                    self.agc[u] = bool(act.get("on"))
                    self.agc_hz[u] = min(max(float(act.get("hz", F0)), 59.8), 60.2)
                elif op == "set_v":
                    u = self._my_unit(a, act.get("unit"))
                    self.vset[u] = min(max(float(act.get("pu")), 0.95), 1.08)
                    self.need_pf = True
                elif op == "renewable":
                    u = self._my_unit(a, act.get("unit"))
                    if self.u_kind[u] not in RENEW:
                        raise ValueError("renewable: not a wind or solar unit")
                    self.renew_on[u] = bool(act.get("on"))
                    if "mw" in act:
                        self.ptarget[u] = min(max(float(act["mw"]), 0.0), self.u_pmax[u])
                    else:
                        self.ptarget[u] = self.u_pmax[u]
                    self.need_pf = True
                elif op == "feeder":
                    f = self.f_idx.get(act.get("feeder"))
                    if f is None or self.fd_area[f] != a:
                        raise ValueError(f"feeder: {act.get('feeder')} is not a feeder of your area")
                    on = bool(act.get("on"))
                    if not self._remote_ok(self.fd_bus[f]):
                        raise ValueError(f"feeder {act['feeder']}: no remote control at its substation")
                    if on != self.fd_on[f]:
                        self.fd_on[f] = on
                        if on and self.island[self.fd_bus[f]] >= 0:
                            self._pickup(f)
                        self.need_pf = True
                elif op == "shunt":
                    s = self.sh_idx.get(act.get("shunt"))
                    if s is None or self.sh_area[s] != a:
                        raise ValueError(f"shunt: {act.get('shunt')} is not a reactor of your area")
                    self.sh_on[s] = bool(act.get("on"))
                    self.need_pf = True
                elif op == "equip":
                    self.eq.command(a, act)
                elif op == "dispatch":
                    c = self.crew_idx.get(act.get("crew"))
                    if c is None or self.crews[c]["area"] != a:
                        raise ValueError(f"dispatch: {act.get('crew')} is not your crew")
                    bus = self.idx.get(act.get("bus"))
                    if bus is None or self.bus_area[bus] != a:
                        raise ValueError(f"dispatch: {act.get('bus')} is not a bus of your area")
                    C = self.crews[c]
                    B = self.g["buses"]
                    d = math.dist((B[C["at"]]["x"], B[C["at"]]["y"]), (B[bus]["x"], B[bus]["y"])) * 1.3
                    C.update(to=bus, eta=self.t + 10 + d / C["kmh"] * 60, task=None, task_target=None)
                    self.ev(a, f"{C['id']} driving to {B[bus]['id']}, arrives at {C['eta']:.0f} min")
                elif op == "repair":
                    k = self.br_idx.get(act.get("branch"))
                    c = self.crew_idx.get(act.get("crew"))
                    if k is None or c is None or self.crews[c]["area"] != a:
                        raise ValueError("repair: needs your crew and a branch")
                    C = self.crews[c]
                    if C["to"] is not None or C["at"] not in (self.bf[k], self.bt[k]):
                        raise ValueError(f"repair: {C['id']} is not at an end of {act['branch']}")
                    if self.closed[k]:
                        raise ValueError(f"repair: open {act['branch']} first")
                    if C["task"] == "rtu":
                        raise ValueError(f"repair: {C['id']} is restoring the RTU here until {C['task_end']:.0f} min")
                    found = k in self.faulted and k not in self.fault_known
                    if k in self.faulted:
                        self.fault_known.add(k)
                    C.update(task="repair", task_target=k,
                             task_end=self.t + (FAULT_REPAIR_MIN if k in self.faulted else SWITCH_REPAIR_MIN))
                    self.ev(a, f"{C['id']} working on {act['branch']} until {C['task_end']:.0f} min"
                               + (" (found a permanent fault on the line)" if found else ""))
                else:
                    raise ValueError(f"unknown op {op!r}")
            except (ValueError, TypeError, KeyError) as e:
                self.ev(a, f"command refused: {e}")
        for k, who in tie_close.items():
            if len(who) < 2:
                other = [o for o in self.br_owner[k] if o not in who]
                for a in who:
                    self.ev(a, f"tie {self.g['branches'][k]['id']}: waiting for {G.area_name(other[0])} to close it in the same step")

    def _my_unit(self, a, uid):
        u = self.u_idx.get(uid)
        if u is None or self.u_area[u] != a:
            raise ValueError(f"{uid} is not a unit of your area")
        why = self.eq.unit_cmd_refused(u)
        if why:
            raise ValueError(f"{uid}: {why}")
        return u

    def _start(self, a, uid):
        u = self._my_unit(a, uid)
        k = self.u_kind[u]
        if self.state[u] == "unavailable":
            raise ValueError(f"{uid} is out for maintenance")
        if self.state[u] != "off":
            raise ValueError(f"{uid} is {self.state[u]}")
        if k == "nuclear":
            raise ValueError(f"{uid}: a nuclear unit cannot restart within this horizon; restore its off-site power")
        if k in RENEW:
            raise ValueError(f"{uid}: use op 'renewable' for wind and solar")
        if self.energy[u] <= 0:
            raise ValueError(f"{uid}: {'reservoir' if k == 'hydro' else 'fuel'} exhausted")
        if self.t < self.lock_until[u]:
            raise ValueError(f"{uid} tripped recently; it can start again at {self.lock_until[u]:.0f} min")
        bus = self.u_bus[u]
        U = self.g["units"][u]
        if self.island[bus] < 0 and not U["black_start"]:
            why = self.eq.dead_bus_start(u)
            if why:
                raise ValueError(f"{uid} {why}")
        why = self.eq.start_refused(u)
        if why:
            raise ValueError(f"{uid}: {why}")
        first = self.eq.start_now(u)
        if first is not None:
            # resynchronised from house load: online within the step at the boiler's minimum firing
            self.state[u] = "online"
            self.online_since[u] = self.t
            if self.first_online[u] < 0:
                self.first_online[u] = self.t
            self.pm[u] = self.pset[u] = self.ptarget[u] = first
            self.ev(a, f"{uid} resynchronised from house load at {first:.0f} MW")
            self._components()
            return
        if self.island[bus] >= 0 and U["crank_mw"] > 0:
            lab = self.island[bus]
            head = sum(self.u_pmax[v] - self.pm[v] for v in self._island_units(lab))
            if head < U["crank_mw"]:
                raise ValueError(f"{uid} needs {U['crank_mw']:.0f} MW to crank; its island has {head:.0f} MW of headroom")
        heat, dur = self._heat(u)
        self.eq.on_start(u, heat)
        self.state[u] = "starting"
        self.start_begin[u] = self.t
        self.start_end[u] = self.t + dur
        self.ev(a, f"{uid} starting ({heat} start, {dur:.0f} min)")

    def _heat(self, u):
        """A unit's thermal state now and the minutes a start would take from it."""
        U = self.g["units"][u]
        off_h = (self.t - self.last_off[u]) / 60.0
        if off_h <= U["hot_window_h"]:
            return "hot", U["start_hot"]
        if off_h <= U.get("warm_window_h", U["hot_window_h"]):
            return "warm", U.get("start_warm", U["start_cold"])
        return "cold", U["start_cold"]

    def _pickup(self, f):
        why = self.eq.pickup_refused(f)
        if why:
            self.fd_on[f] = False
            self.ev(int(self.fd_area[f]), f"feeder {self.g['loads'][f]['id']}: {why}")
            return
        h = (self.t - self.fd_dark_since[f]) / 60.0 if self.fd_served_since[f] < 0 else 0.0
        self.fd_peak[f] = 1.0 + (self.clpu_f[f] - 1.0) * min(1.0, max(0.0, h) / 4.0)
        self.fd_served_since[f] = self.t
        self.eq.on_pickup(f, float(self._demand_mw(self.t)[f]) * self.fd_peak[f])

    def _close(self, k, a, force, both):
        L = self.g["branches"][k]
        name = L["id"]
        if self.closed[k]:
            return
        if not (self._remote_ok(self.bf[k]) or self._remote_ok(self.bt[k])):
            self.ev(both, f"close {name}: no remote control (substation batteries exhausted); send a crew")
            return
        if k in self.stuck:
            self.stuck_known.add(k)
            self.ev(both, f"close {name}: BREAKER FAILED TO OPERATE (a crew can fix it)")
            return
        fi, ti = self.bf[k], self.bt[k]
        lf, lt = self.island[fi], self.island[ti]
        if lf < 0 and lt < 0:
            self.closed[k] = True
            self.ev(both, f"{name} closed (both ends dead)")
            self._components()
            return
        if lf >= 0 and lt >= 0:
            if lf == lt:
                d = math.degrees(np.angle(self.V[fi]) - np.angle(self.V[ti]))
                if abs(d) > LOOP_ANGLE and not force:
                    self.ev(both, f"close {name}: synchro-check blocked, standing angle {d:.0f} deg > {LOOP_ANGLE:.0f}")
                    return
                self.closed[k] = True
                if abs(d) > LOOP_ANGLE:
                    self.damage += 1
                    self.closed[k] = False
                    self.ev(both, f"{name} forced closed at {d:.0f} deg: power surge, line tripped, equipment damaged")
                    return
                self.ev(both, f"{name} closed (loop, {d:.0f} deg)")
                self.need_pf = True
                return
            # two islands
            df = self.f_bus[fi] - self.f_bus[ti]
            dv = abs(abs(self.V[fi]) - abs(self.V[ti]))
            th0 = math.degrees((self.th_bus[fi] + np.angle(self.V[fi])) - (self.th_bus[ti] + np.angle(self.V[ti])))
            th0 = (th0 + 180) % 360 - 180
            ok_relay = abs(df) <= SYNC_SLIP_HZ and dv <= SYNC_DV
            window = None
            if ok_relay:
                for j in range(0, 301):                 # 0.1 s resolution over the step
                    th = (th0 + 360 * df * j * 0.1 + 180) % 360 - 180
                    if abs(th) <= SYNC_ANGLE:
                        window = j * 0.1
                        break
            if window is not None:
                self._merge(lf, lt, fi, ti)
                self.closed[k] = True
                self.ev(both, f"{name} closed by synchro-check after {window:.1f} s: islands joined "
                              f"(slip {df:+.3f} Hz, dV {dv:.3f} pu)")
                self._components()
                return
            if not force:
                why = (f"slip {df:+.3f} Hz (limit {SYNC_SLIP_HZ})" if abs(df) > SYNC_SLIP_HZ else
                       f"voltage difference {dv:.3f} pu (limit {SYNC_DV})" if dv > SYNC_DV else
                       f"angle never came within {SYNC_ANGLE:.0f} deg this step (now {th0:.0f} deg)")
                self.ev(both, f"close {name}: synchro-check blocked: {why}")
                return
            if abs(th0) > 30 or abs(df) > 0.3:
                self.out_of_phase = True
                self.damage += 1
                self.ev(both, f"{name} FORCED CLOSED OUT OF PHASE ({th0:.0f} deg, {df:+.2f} Hz): generators damaged; "
                              "both islands lost")
                self.collapse(lf, "out-of-phase closure")
                if self.island[ti] >= 0:
                    self.collapse(self.island[ti], "out-of-phase closure")
                return
            self._merge(lf, lt, fi, ti)
            self.closed[k] = True
            self.ev(both, f"{name} forced closed at {th0:.0f} deg: islands joined with a jolt")
            self._components()
            return
        # one end live: energise the dead side
        live, dead = (fi, ti) if lf >= 0 else (ti, fi)
        lab = self.island[live]
        energiser = self.bus_area[live]
        # Each energisation is a switching step the control room prepares and then checks (voltages, relays) before
        # the next: one every ENERGISE_INTERVAL_MIN minutes per room, whatever the outcome.
        if self.t < self.last_energise[energiser] + ENERGISE_INTERVAL_MIN - 1e-9:
            self.ev(both, f"close {name}: {G.area_name(energiser)} is still checking its last energisation; its next "
                          f"one can be from {self.last_energise[energiser] + ENERGISE_INTERVAL_MIN:.1f} min")
            return
        self.last_energise[energiser] = self.t
        if k in self.faulted:
            self.fault_known.add(k)
            cap = self._online_cap(lab)
            self.ev(both, f"{name} TRIPPED ON CLOSE: permanent fault (distance relay); the line needs a repair crew")
            if cap < 100:
                self.collapse(lab, f"closing onto the fault on {name} pulled the weak island ({cap:.0f} MW online) down")
            return
        section = self._dead_section(dead)
        why = self.eq.close_refused(k, section)
        if why:
            self.ev(both, f"close {name}: {why}")
            return
        inrush = self._inrush(section, energiser) + self.br_b[k] * G.BASE_MVA
        cap = self._online_cap(lab)
        ratio = self.priv[energiser]["inrush_ratio"]
        if inrush > ratio * cap:
            self.ev(both, f"{name} tripped on energisation: {inrush:.0f} MVA of charging and inrush into an island "
                          f"with {cap:.0f} MW online")
            return
        why = self.eq.energise_refused(k, section, cap)
        if why:
            self.ev(both, f"{name} tripped on energisation: {why}")
            return
        # Transformer inrush can make a differential or overcurrent relay operate although nothing is wrong; the
        # nearer the energisation is to the island's limit, the likelier.
        n_tx = sum(1 for i in section if i in self.fd_bus_set or i in self.u_bus_set)
        tries = int(self.energise_tries[k])
        self.energise_tries[k] += 1
        if (n_tx and self.s.get("inrush_trips", True)
                and _u01(self.s["seed"], "inrush", k, tries) < 0.02 + 0.25 * (inrush / (ratio * cap)) ** 2):
            self.ev(both, f"{name} tripped on energisation: a relay operated on transformer inrush "
                          f"({inrush:.0f} MVA into {cap:.0f} MW online); nothing is damaged, it may be tried again")
            return
        self.closed[k] = True
        newly = self._components()
        for f in range(self.nf):
            if self.fd_on[f] and self.fd_bus[f] in newly:
                self._pickup(f)
        self.ev(both, f"{name} closed: energised {len(section)} dead bus{'es' if len(section) > 1 else ''}")

    def _merge(self, lf, lt, fi, ti):
        """Keep the bigger island's frequency and phase for the joined island."""
        cf, ct = self._online_cap(lf), self._online_cap(lt)
        keep, other = (lf, lt) if cf >= ct else (lt, lf)
        mk = self.island == keep
        mo = self.island == other
        self.f_bus[mo] = self.f_bus[np.flatnonzero(mk)[0]]
        self.th_bus[mo] = self.th_bus[np.flatnonzero(mk)[0]]

    # ------------------------------------------------------------------ physics
    def _demand_mw(self, minute):
        return self.fd_mw * SC.load_profile(self.s["start_hour"], minute) * self.s["load_scale"]

    def _feeder_draw(self, base):
        """Each live, closed feeder's present draw (MW) with cold load pickup."""
        on = self.fd_on & (self.island[self.fd_bus] >= 0)
        mult = np.ones(self.nf)
        age = self.t - self.fd_served_since
        hot = on & (self.fd_served_since >= 0)
        mult[hot] = 1.0 + (self.fd_peak[hot] - 1.0) * np.exp(-age[hot] / self.clpu_tau[hot])
        return self.eq.adjust_draw(np.where(on, base * mult, 0.0), on), on

    def _crank(self, u):
        """A starting unit's auxiliaries come on over its first ten minutes."""
        return self.g["units"][u]["crank_mw"] * min(1.0, max(0.0, (self.t - self.start_begin[u]) / 10.0))

    def _renew_avail(self, u):
        if self.u_kind[u] == "wind":
            return self.u_pmax[u] * self.wind_scale
        return self.u_pmax[u] * self.s["solar"] * SC.solar_profile(self.s["start_hour"], self.t)

    def physics(self):
        dt_step = SC.STEP_S
        # unit timers: starts finishing, crews
        for u in range(self.nu):
            if self.state[u] == "starting":
                bus = self.u_bus[u]
                U = self.g["units"][u]
                if self.island[bus] < 0 and not U["black_start"] and not self.eq.can_black_start(u):
                    self.state[u] = "off"
                    self.ev(self.u_area[u], f"{U['id']} start aborted: its bus lost power")
                    continue
                if self.t >= self.start_end[u]:
                    n = int(self.attempts[u])
                    self.attempts[u] += 1
                    if u in self.damaged:
                        self.state[u] = "unavailable"
                        self.ev(self.u_area[u], f"{U['id']} START FAILED: damage from the trip found (bearing / "
                                                f"turbine); out of service for the rest of the restoration")
                        continue
                    seq = self.start_fail.get(u)
                    if seq and n < len(seq) and seq[n]:
                        self.state[u] = "off"
                        retry = U.get("retry_min", 30)
                        self.lock_until[u] = self.t + retry
                        why = ["fuel valve fault", "flame failure", "excitation fault", "failed to synchronise",
                               "lube oil pressure trip"][int(_u01(self.s["seed"], "why", u, n) * 5)]
                        self.ev(self.u_area[u], f"{U['id']} START FAILED ({why}); can retry from {self.t + retry:.0f} min")
                        continue
                    self.state[u] = "online"
                    self.online_since[u] = self.t
                    if self.first_online[u] < 0:
                        self.first_online[u] = self.t
                    p0 = 0.0     # a unit synchronises at no load and is loaded by its setpoint
                    self.pm[u] = p0; self.pset[u] = p0; self.ptarget[u] = max(self.ptarget[u], p0)
                    if self.island[bus] < 0:
                        sec = self._dead_section(bus)
                        inrush = self._inrush(sec, self.u_area[u], skip_bus=int(bus))
                        lim = self.priv[self.u_area[u]]["inrush_ratio"] * self.u_pmax[u]
                        lim = min(lim, self.eq.dead_start_limit(u) or math.inf)
                        if inrush > lim:
                            self._stop_unit(u, trip=True)
                            self.ev(self.u_area[u], f"{U['id']} tripped as it came up: {inrush:.0f} MVA of connected "
                                                    f"network to energise (open breakers first)")
                            continue
                        newly = self._components()
                        for f in range(self.nf):
                            if self.fd_on[f] and self.fd_bus[f] in newly:
                                self._pickup(f)
                        self.ev(self.u_area[u], f"{U['id']} online: black start, energised {len(sec)} bus(es)")
                    else:
                        self.ev(self.u_area[u], f"{U['id']} online, synchronised at {p0:.0f} MW")
                    self._components()
        for C in self.crews:
            if C["to"] is not None and self.t >= C["eta"]:
                C["at"], C["to"] = C["to"], None
                self.ev(C["area"], f"{C['id']} arrived at {self.bus_id[C['at']]}")
                if C["at"] in self.scada_lost:
                    C.update(task="rtu", task_end=self.t + RTU_FIX_MIN, task_target=None)
                    self.ev(C["area"], f"{C['id']}: RTU at {self.bus_id[C['at']]} failed; restoring it "
                                       f"until {self.t + RTU_FIX_MIN:.0f} min (local control meanwhile)")
            if C["task"] == "rtu" and self.t >= C["task_end"]:
                self.scada_lost.discard(C["at"])
                C["task"] = None
                self.ev(C["area"], f"{C['id']}: RTU at {self.bus_id[C['at']]} restored (telemetry and remote control back)")
            if C["task"] == "repair" and self.t >= C["task_end"]:
                k = C["task_target"]
                self.faulted.discard(k); self.fault_known.discard(k); self.stuck.discard(k); self.stuck_known.discard(k)
                self.relay_misop.pop(k, None)
                C["task"] = None
                self.ev(self.br_owner[k], f"{C['id']} finished work on {self.g['branches'][k]['id']}: it can be closed")
        self.eq.step()
        # early-life trips of units back online for the first time
        for u, after in list(self.early_trip.items()):
            if self.state[u] == "online" and self.first_online[u] >= 0 and self.t >= self.first_online[u] + after:
                del self.early_trip[u]
                self._stop_unit(u, trip=True)
                self.ev(self.u_area[u], f"{self.g['units'][u]['id']} TRIPPED {after:.0f} min after coming back "
                                        f"({['drum level', 'feed pump', 'control system', 'vibration'][u % 4]})")
                self._components()
        # scheduled events
        evs = self.s["events"]
        while self.ev_i < len(evs) and evs[self.ev_i][0] <= self.t:
            m, kind, i = evs[self.ev_i]
            self.ev_i += 1
            if kind == "unit_trip" and self.state[i] == "online":
                self._stop_unit(i, trip=True)
                self.ev(self.u_area[i], f"{self.g['units'][i]['id']} TRIPPED (boiler feed pump failure)")
                self._components()
            elif kind == "line_trip" and self.closed[i]:
                self.closed[i] = False
                self.faulted.add(i); self.fault_known.add(i)
                self.ev(self.br_owner[i], f"{self.g['branches'][i]['id']} TRIPPED on a fault (tree contact); needs a crew")
                self._components()
            elif kind == "wind_drop":
                self.wind_scale = max(0.05, self.wind_scale * 0.3)
                self.ev(list(range(G.N_AREAS)), "weather: wind speeds falling across the country")
        self._dynamics(dt_step)
        self._thermal_limits()
        self.since_pf += 1
        if self.need_pf or self.since_pf >= 10:
            self._powerflow()
        self._accounting()

    def _dynamics(self, dt_step):
        base = self._demand_mw(self.t)
        draw, on = self._feeder_draw(base)
        isl = self.islands()
        if not isl:
            return
        labels = list(isl.keys())
        for lab in labels:
            if lab not in self.islands():
                continue
            members = np.flatnonzero(self.island == lab)
            mset = set(members.tolist())
            us = [u for u in range(self.nu) if self.state[u] == "online" and self.island[self.u_bus[u]] == lab]
            syn = [u for u in us if self.u_sync[u]]
            if not syn:
                continue
            ren = [u for u in us if not self.u_sync[u]]
            fd = np.flatnonzero(on & np.isin(self.fd_bus, members))
            pload = float(draw[fd].sum())
            crank = sum(self._crank(u) for u in range(self.nu)
                        if self.state[u] == "starting" and self.island[self.u_bus[u]] == lab)
            pload += crank
            pload -= self.eq.injection(mset)
            # renewables: weak-grid limit
            syn_cap = float(sum(self.u_pmax[u] for u in syn))
            pren = 0.0
            f_now = float(self.f_bus[members[0]])
            for u in ren:
                # inverters curtail above 60.2 Hz (frequency-watt), 40 % of output per Hz
                fw = max(0.0, 1.0 - 0.4 * max(0.0, f_now - 60.2))
                self.pm[u] = min(self.ptarget[u], self._renew_avail(u)) * fw
                pren += self.pm[u]
            if ren and pren > 0.3 * syn_cap:
                for u in ren:
                    self._stop_unit(u)
                    self.renew_on[u] = False
                self.ev(sorted(set(self.u_area[ren].tolist())),
                        f"inverters tripped: {pren:.0f} MW of wind/solar in an island with only {syn_cap:.0f} MW synchronous")
                pren = 0.0
            S = np.array(syn)
            pmax = self.u_pmax[S]; H = self.u_H[S]; Tg = self.u_Tg[S]
            gf, tgf = self.eq.gov_factors(syn)
            Tg = Tg * np.array(tgf)
            # setpoints move toward targets at the ramp rate
            for u in syn:
                step = self.u_ramp[u] * dt_step / 60.0
                self.pset[u] += float(np.clip(self.ptarget[u] - self.pset[u], -step, step))
            pm = self.pm[S].copy(); ps = self.pset[S].copy(); agc = self.agc[S]
            f = float(self.f_bus[members[0]])
            Ht = float((H * pmax).sum())
            imb = pm.sum() + pren - pload * (1 + 0.02 * (f - F0))
            gov = pmax / (0.05 * F0)
            # A governor picks up only its primary reserve within seconds (a boiler or a steam cycle cannot follow
            # faster); the rest of a load step has to come from setpoints at the unit's ramp rate.
            glim = self.u_gov[S] * pmax * np.array(gf)

            def gov_target(ps, f):
                return np.clip(ps + np.clip(-gov * (f - F0), -glim, glim), 0, pmax)
            fref = float(self.agc_hz[S][agc].mean()) if agc.any() else None
            settled = (abs(imb) < 0.3 and (fref is None or abs(f - fref) < 0.002)
                       and np.allclose(pm, gov_target(ps, f), atol=0.3))
            fmin = fmax = f
            th = float(self.th_bus[members[0]])
            if not settled:
                t = 0.0
                shed_stages = set()
                while t < dt_step - 1e-9:
                    dt = 0.25 if t < 12 else 0.5
                    if agc.any():
                        n_agc = agc.sum()
                        ps = ps + agc * np.minimum(self.u_ramp[S] / 60.0 * dt, np.abs((fref - f) * syn_cap * 0.02 * dt / n_agc)) * np.sign(fref - f)
                        ps = np.clip(ps, 0, pmax)
                    target = gov_target(ps, f)
                    pm = pm + (target - pm) * min(1.0, dt / Tg.min()) * (Tg.min() / Tg)
                    pe = pload * (1 + 0.02 * (f - F0))
                    f = f + F0 / (2 * Ht) * (pm.sum() + pren - pe) * dt
                    th += 2 * math.pi * (f - F0) * dt
                    fmin, fmax = min(fmin, f), max(fmax, f)
                    t += dt
                    for stage, hz in ((1, 59.0), (2, 58.7), (3, 58.4)):
                        if f < hz and stage not in shed_stages:
                            shed_stages.add(stage)
                            hit = fd[(self.fd_stage[fd] == stage) & self.fd_on[fd]]
                            if hit.size:
                                self.fd_on[hit] = False
                                pload -= float(draw[hit].sum())
                                self.ev(sorted(set(self.fd_area[hit].tolist())),
                                        f"UFLS stage {stage}: frequency {f:.2f} Hz, shed {draw[hit].sum():.0f} MW on {hit.size} feeders")
                    if f < UF_COLLAPSE:
                        break
                self.pm[S] = pm
                self.pset[S] = ps
                for j, u in enumerate(syn):
                    if agc[j]:
                        self.ptarget[u] = ps[j]
            else:
                th += 2 * math.pi * (f - F0) * dt_step
            self.f_bus[members] = f
            self.th_bus[members] = th % (2 * math.pi)
            # energy-limited units
            for u in syn:
                if np.isfinite(self.energy[u]):
                    self.energy[u] -= self.pm[u] * dt_step / 3600.0
                    if self.energy[u] <= 0:
                        self.energy[u] = 0
                        self._stop_unit(u)
                        self.ev(self.u_area[u], f"{self.g['units'][u]['id']} stopped: {'reservoir' if self.u_kind[u] == 'hydro' else 'fuel'} exhausted")
            if f < UF_COLLAPSE:
                self.collapse(lab, f"frequency fell to {f:.2f} Hz (nadir) after {pload:.0f} MW of demand met "
                                   f"{float(self.pm[S].sum()):.0f} MW of generation")
            elif fmax > 63.5 or f > OF_TRIP:
                big = max(syn, key=lambda u: self.pm[u])
                self._stop_unit(big, trip=True)
                self.ev(self.u_area[big], f"{self.g['units'][big]['id']} tripped on over-frequency "
                                          f"(peak {fmax:.2f} Hz, {f:.2f} Hz at the end of the step)")
                self._components()
                if not any(self.state[u] == "online" for u in syn):
                    pass
        # islands that lost every synchronous unit are dark now (components handles it)
        self._components() if any(self.state[u] != "online" and self.island[self.u_bus[u]] >= 0 and self.u_sync[u]
                                   for u in range(self.nu)) else None

    def _thermal_limits(self):
        for u in range(self.nu):
            if self.state[u] != "online" or self.u_kind[u] not in ("ccgt", "coal") or self.eq.soaking(u):
                continue
            grace = self.online_since[u] + self.u_pmin[u] / max(self.u_ramp[u], 0.1)
            if self.pm[u] < self.u_pmin[u] - 0.5 and self.t > grace:
                if self.below_pmin[u] < 0:
                    self.below_pmin[u] = self.t
                elif self.t - self.below_pmin[u] > 20:
                    self._stop_unit(u, trip=True)
                    self.ev(self.u_area[u], f"{self.g['units'][u]['id']} tripped: below minimum stable load "
                                            f"({self.u_pmin[u]:.0f} MW) for 20 min")
                    self._components()
            else:
                self.below_pmin[u] = -1.0

    def _powerflow(self):
        self.need_pf = False
        self.since_pf = 0
        base = self._demand_mw(self.t)
        draw, on = self._feeder_draw(base)
        for lab, members in list(self.islands().items()):
            if lab not in set(self.island.tolist()):
                continue
            members = np.flatnonzero(self.island == lab)
            loc = {int(b): i for i, b in enumerate(members)}
            n = len(members)
            ks = [k for k in np.flatnonzero(self.closed) if self.bf[k] in loc and self.bt[k] in loc]
            ks = np.array(ks, int)
            br = (np.array([loc[self.bf[k]] for k in ks], int), np.array([loc[self.bt[k]] for k in ks], int),
                  self.br_r[ks], self.br_x[ks], self.br_b[ks])
            p = np.zeros(n); q = np.zeros(n); shb = np.zeros(n)
            fds = np.flatnonzero(on & np.isin(self.fd_bus, members))
            for f in fds:
                i = loc[self.fd_bus[f]]
                p[i] -= draw[f] / G.BASE_MVA
                q[i] -= draw[f] * self.fd_tan[f] / G.BASE_MVA
            for b, mw, mvar in self.eq.injections():
                if b in loc:
                    p[loc[b]] += mw / G.BASE_MVA
                    q[loc[b]] += mvar / G.BASE_MVA
            for s in np.flatnonzero(self.sh_on):
                if self.sh_bus[s] in loc:
                    shb[loc[self.sh_bus[s]]] -= self.sh_mvar[s] / G.BASE_MVA
            gens = []
            syn = []
            for u in range(self.nu):
                if self.island[self.u_bus[u]] != lab:
                    continue
                if self.state[u] == "starting" and self.g["units"][u]["crank_mw"] > 0:
                    p[loc[self.u_bus[u]]] -= self._crank(u) / G.BASE_MVA
                if self.state[u] != "online":
                    continue
                if self.u_sync[u]:
                    U = self.g["units"][u]
                    gens.append((loc[self.u_bus[u]], self.pm[u] / G.BASE_MVA, self.vset[u], U["qmin"] / G.BASE_MVA,
                                 U["qmax"] / G.BASE_MVA))
                    syn.append(u)
                else:
                    p[loc[self.u_bus[u]]] += self.pm[u] / G.BASE_MVA
            if not syn:
                continue
            for b, qlim in self.eq.pf_gens():
                if b in loc:
                    gens.append((loc[b], 0.0, 1.0, -qlim / G.BASE_MVA, qlim / G.BASE_MVA))
            ref = loc[self.u_bus[max(syn, key=lambda u: self.u_pmax[u])]]
            Vi = self.V[members].copy()
            fresh = np.abs(Vi) < 0.5
            Vi[fresh] = 1.0
            res = PF.solve(n, br, shb, p, q, gens, ref, V_init=Vi)
            if res is None:
                res = PF.solve(n, br, shb, p, q, gens, ref)
            areas = sorted(set(self.bus_area[members].tolist()))
            if res is None:
                self.collapse(lab, "voltage collapse: the power flow has no solution (too much load or reactive demand "
                                   "for the online units)")
                continue
            V = res["V"]
            self.V[members] = V
            vm = np.abs(V)
            # reactive output by unit
            for u in syn:
                i = loc[self.u_bus[u]]
                same = [w for w in syn if loc[self.u_bus[w]] == i]
                self.qg[u] = res["qbus"][i] * G.BASE_MVA * self.u_pmax[u] / sum(self.u_pmax[w] for w in same)
            over = vm > V_TRIP
            self.ov_count[members[~over]] = 0
            self.ov_count[members[over]] += 1
            if over.any():
                self.need_pf = True
            if vm.max() > V_DAMAGE or (over.any() and self.ov_count[members].max() >= 2):
                i = int(np.argmax(vm))
                bus = members[i]
                self.ov_count[bus] = 0
                if vm.max() > V_DAMAGE:
                    self.damage += 1
                tripped = [k for k in self.bus_branches[bus] if self.closed[k]]
                for k in tripped:
                    self.closed[k] = False
                self.ev(areas, f"OVERVOLTAGE {vm.max():.3f} pu at {self.bus_id[bus]}: protection opened "
                               f"{', '.join(self.g['branches'][k]['id'] for k in tripped)}"
                        + (" (equipment damaged)" if vm.max() > V_DAMAGE else ""))
                self._components()
                continue
            if vm.min() < V_LOW:
                i = int(np.argmin(vm))
                bus = members[i]
                hit = [f for f in fds if self.fd_bus[f] == bus and self.fd_on[f]]
                if hit:
                    self.fd_on[hit[0]] = False
                    self.ev(self.bus_area[bus], f"undervoltage {vm.min():.3f} pu at {self.bus_id[bus]}: "
                                                f"feeder {self.g['loads'][hit[0]]['id']} dropped")
            Sf, St = PF.branch_flows(V, br)
            load = np.maximum(np.abs(Sf), np.abs(St)) * G.BASE_MVA / self.br_rating[ks]
            self.flow = getattr(self, "flow", np.zeros(self.nl))
            self.loading = getattr(self, "loading", np.zeros(self.nl))
            self.flow[ks] = Sf.real * G.BASE_MVA
            self.loading[ks] = load
            for j in np.flatnonzero(load > 0.5):
                k = int(ks[j])
                if k in self.relay_misop and load[j] > self.relay_misop[k] and self.closed[k]:
                    self.closed[k] = False
                    self.ev(self.br_owner[k], f"{self.g['branches'][k]['id']} TRIPPED: distance relay operated at "
                                              f"{100 * load[j]:.0f}% loading (load encroachment, relay setting "
                                              f"error); a crew can correct it")
                    self.need_pf = True
            if any(not self.closed[int(k)] for k in ks):
                self._components()
                continue
            over = ks[load > 1.25]
            self.overload_count[ks[load <= 1.25]] = 0
            self.overload_count[over] += 1
            if over.size:
                self.need_pf = True
            for k in over[self.overload_count[over] >= 4]:
                self.closed[k] = False
                self.overload_count[k] = 0
                self.ev(self.br_owner[k], f"{self.g['branches'][k]['id']} TRIPPED on overload")
                self._components()

    def _accounting(self):
        base = self._demand_mw(self.t)
        served = self.fd_on & (self.island[self.fd_bus] >= 0)
        h = SC.STEP_S / 3600.0
        self.served_w += float((base * self.fd_w * served).sum()) * h
        self.demand_w += float((base * self.fd_w).sum()) * h
        self.served_mwh += float((base * served).sum()) * h
        self.demand_mwh += float(base.sum()) * h
        share = float((base * self.fd_w * served).sum()) / max(1e-9, float((base * self.fd_w).sum()))
        self.share_sq += share * share
        self.n_steps += 1
        for f in np.flatnonzero(~served & (self.fd_served_since >= 0)):
            self.fd_served_since[f] = -1.0
            self.fd_dark_since[f] = self.t
        for uid, dl in self.s["nuclear_deadline_h"].items():
            if uid in self.nuclear_done:
                continue
            u = self.u_idx[uid]
            aux = [f for f in range(self.nf) if self.g["loads"][f].get("nuclear_aux") == uid][0]
            ok = self.eq.offsite_ok(uid)
            if (served[aux] if ok is None else ok):
                self.nuclear_done.add(uid)
                self.ev(self.u_area[u], f"{uid}: off-site power restored to the cooling systems")
            elif self.t >= dl * 60:
                self.nuclear_done.add(uid)
                self.nuclear_missed.append(uid)
                self.ev(self.u_area[u], f"{uid}: BACKUP DIESELS EXHAUSTED before off-site power returned (safety event)")

    # ------------------------------------------------------------------ the loop
    def step(self, actions_by_area):
        self.apply(actions_by_area)
        self.physics()
        self.step_i += 1
        self.t = self.step_i * SC.STEP_S / 60.0
        if self.step_i % 20 == 0:
            self.timeline.append(dict(t=round(self.t, 1), served_mw=round(float((self._demand_mw(self.t) * (self.fd_on & (self.island[self.fd_bus] >= 0))).sum()), 1),
                                      demand_mw=round(float(self._demand_mw(self.t).sum()), 1),
                                      islands=len(self.islands()), live_buses=int((self.island >= 0).sum())))

    def done(self):
        return self.t >= self.horizon - 1e-9

    def score(self):
        frac = self.served_w / self.demand_w if self.demand_w else 0.0
        # The restoration index: the mean over steps of the squared (priority-weighted) share of demand served, so
        # the last 20% of the country counts as much as the 40% before it.
        index = self.share_sq / self.n_steps if self.n_steps else 0.0
        mult = PEN_COLLAPSE ** self.collapses * PEN_NUCLEAR ** len(self.nuclear_missed) * PEN_DAMAGE ** self.damage
        pen = 1.0 - mult
        raw = 0.0 if self.out_of_phase else index * mult
        # The score: the raw score over the capacity bound (bound.py), the index no restoration of this scenario can
        # beat over the same steps, so 1.0 is the physical maximum.
        cap, _ = BD.index_bound(self.g, self.s, self.n_steps, PRIORITY_WEIGHT)
        sc = raw / cap if cap > 0 else 0.0
        return dict(score=round(sc, 6), raw_score=round(raw, 6), bound=round(cap, 6),
                    restoration_index=round(index, 6), served_fraction=round(frac, 6),
                    served_mwh=round(self.served_mwh, 1),
                    demand_mwh=round(self.demand_mwh, 1), collapses=self.collapses, nuclear_missed=self.nuclear_missed,
                    damage=self.damage, out_of_phase=self.out_of_phase, penalty=round(pen, 4))

    # ------------------------------------------------------------------ what an area sees
    def observe(self, a):
        B, L, U, LD = self.g["buses"], self.g["branches"], self.g["units"], self.g["loads"]
        my_buses = self.area_buses[a]
        tele = {int(i): bool(self._remote_ok(i, control=False)) for i in my_buses}
        flow = getattr(self, "flow", np.zeros(self.nl)); loading = getattr(self, "loading", np.zeros(self.nl))
        buses = {}
        for i in my_buses:
            i = int(i)
            if not tele[i]:
                buses[self.bus_id[i]] = dict(telemetry=False)
                continue
            live = self.island[i] >= 0
            buses[self.bus_id[i]] = dict(
                telemetry=True, live=bool(live),
                v=round(float(abs(self.V[i])), 4) if live else 0.0,
                angle=round(math.degrees(float(np.angle(self.V[i]))), 2) if live else None,
                f=round(float(self.f_bus[i]), 4) if live else None,
                island=self.bus_id[int(self.island[i])] if live else None,
                battery_h=None if live else round(max(0.0, self.battery_h[i] - (self.t - self.dark_since[i]) / 60), 2))
        branches = {}
        for k in self.area_branches[a]:
            f_, t_ = int(self.bf[k]), int(self.bt[k])
            seen = bool(tele.get(f_) or tele.get(t_))
            d = dict(closed=bool(self.closed[k]) if seen else None, fault_found=k in self.fault_known,
                     failed_to_operate=k in self.stuck_known)
            if seen and self.closed[k] and self.island[f_] >= 0:
                d.update(mw=round(float(flow[k]), 1), loading=round(float(loading[k]), 3))
            if self.br_tie[k]:
                other = [o for o in self.br_owner[k] if o != a][0]
                mine, theirs = (f_, t_) if self.bus_area[f_] == a else (t_, f_)
                d.update(tie=True, neighbour=G.area_name(other))
                sides = {}
                for nm, i in (("this_side", mine), ("other_side", theirs)):
                    live = self.island[i] >= 0
                    sides[nm] = dict(bus=self.bus_id[i], live=bool(live), f=round(float(self.f_bus[i]), 4) if live else None,
                                     v=round(float(abs(self.V[i])), 4) if live else None)
                d.update(sides)
                if self.island[mine] >= 0 and self.island[theirs] >= 0 and not self.closed[k]:
                    th = math.degrees((self.th_bus[mine] + np.angle(self.V[mine])) - (self.th_bus[theirs] + np.angle(self.V[theirs])))
                    d["sync_angle"] = round((th + 180) % 360 - 180, 1)
                    d["slip_hz"] = round(float(self.f_bus[mine] - self.f_bus[theirs]), 4)
            branches[L[k]["id"]] = d
        units = {}
        for u in self.area_units[a]:
            d = dict(state=self.state[u], p=round(float(self.pm[u]), 2), q=round(float(self.qg[u]), 2),
                     p_target=round(float(self.ptarget[u]), 2), p_set=round(float(self.pset[u]), 2),
                     agc=bool(self.agc[u]), agc_hz=round(float(self.agc_hz[u]), 3), v_set=round(float(self.vset[u]), 3))
            if self.state[u] == "starting":
                d["ready_at_min"] = round(float(self.start_end[u]), 1)
            if self.state[u] == "off" and self.u_kind[u] in G.TIMING:
                heat, dur = self._heat(u)
                d.update(hot=heat == "hot", heat=heat, start_min=float(dur))
                if self.lock_until[u] > self.t:
                    d["locked_until_min"] = round(float(self.lock_until[u]), 1)
            if np.isfinite(self.energy[u]):
                d["energy_left_mwh"] = round(float(self.energy[u]), 1)
            if self.u_kind[u] in RENEW:
                d["available_mw"] = round(float(self._renew_avail(u)), 1)
                d["enabled"] = bool(self.renew_on[u])
            if self.u_kind[u] == "nuclear":
                dl = self.s["nuclear_deadline_h"][U[u]["id"]]
                d["cooling_backup_until_min"] = round(dl * 60, 0)
                d["offsite_power"] = U[u]["id"] in self.nuclear_done and U[u]["id"] not in self.nuclear_missed
            units[U[u]["id"]] = d
        if self._draw_cache[0] != self.step_i:
            base = self._demand_mw(self.t)
            self._draw_cache = (self.step_i, base, self._feeder_draw(base)[0])
        _, base, draw = self._draw_cache
        feeders = {}
        for f in self.area_feeders[a]:
            if not tele.get(int(self.fd_bus[f])):
                feeders[LD[f]["id"]] = dict(telemetry=False)
                continue
            feeders[LD[f]["id"]] = dict(on=bool(self.fd_on[f]), live=bool(self.island[self.fd_bus[f]] >= 0),
                                        mw=round(float(draw[f]), 2), demand_mw=round(float(base[f]), 2))
        shunts = {self.g["shunts"][int(s)]["id"]: dict(on=bool(self.sh_on[s])) for s in np.flatnonzero(self.sh_area == a)}
        crews = {}
        for C in self.crews:
            if C["area"] == a:
                crews[C["id"]] = dict(at=self.bus_id[C["at"]] if C["to"] is None else None,
                                      driving_to=self.bus_id[C["to"]] if C["to"] is not None else None,
                                      arrives_min=round(C["eta"], 1) if C["to"] is not None else None,
                                      working_on=(self.g["branches"][C["task_target"]]["id"] if C["task"] == "repair"
                                                  else "rtu" if C["task"] == "rtu" else None),
                                      done_min=round(C["task_end"], 1) if C["task"] else None)
        ev, self.events[a] = self.events[a], []
        allowed = self.messages_allowed(a)
        self.msg_allowed_obs[a] = (allowed, self._telecom_degraded(a))
        weather = dict(kind=self.s["weather"], temperature_c=self.s["temperature_c"],
                       cold_load_severity=self.s["cold_load_severity"], line_rating_factor=self.s["line_rating_factor"])
        obs = dict(step=self.step_i, t_min=round(self.t, 2), horizon_min=SC.HORIZON_MIN, weather=weather, buses=buses,
                   branches=branches, units=units, feeders=feeders, shunts=shunts, crews=crews, events=ev,
                   messages_allowed=allowed)
        eq = self.eq.observe(a)
        if eq:
            obs["equipment"] = eq
        return obs

    def _telecom_degraded(self, a):
        tb = self.telecom_bus[a]
        return self.island[tb] < 0 and self.dark_since[tb] >= 0 and (self.t - self.dark_since[tb]) > self.s["telecom_h"][a] * 60

    def messages_allowed(self, a):
        """Recipients area a may address this step: its banked credits, or one every ten steps on telecom backup."""
        if self._telecom_degraded(a):
            return 1 if self.step_i >= self.msg_budget_next[a] else 0
        return int(self.msg_credits[a])

    def route_messages(self, outboxes):
        """Queue this step's messages (sent in reply to the observation of step n) for delivery with the
        observation of step n + MSG_DELAY_STEPS, within each area's credits; return the inboxes due now."""
        n = self.step_i - 1
        due = self.msg_queue.setdefault(n + MSG_DELAY_STEPS, [[] for _ in range(G.N_AREAS)])
        names = {G.area_name(i): i for i in range(G.N_AREAS)}
        for a, out in enumerate(outboxes):
            allowed, degraded = self.msg_allowed_obs[a]
            spent = 0
            for m in (out if isinstance(out, list) else []):
                if not isinstance(m, dict):
                    continue
                to = m.get("to")
                if to == "all":
                    targets = [i for i in range(G.N_AREAS) if i != a]
                else:
                    targets = sorted({names[x] for x in (to if isinstance(to, list) else [to])
                                      if isinstance(x, str) and x in names and names[x] != a})
                if not targets:
                    continue
                if spent + len(targets) > allowed:
                    self.events[a].append(f"[{self.t:6.1f} min] message to {to} not sent: it needs {len(targets)} "
                                          f"credit(s) and {allowed - spent} are left"
                                          + (" (telecom node on backup)" if degraded else ""))
                    continue
                text = str(m.get("text", ""))[:MAX_MESSAGE_CHARS]
                for t in targets:
                    due[t].append(dict(sender=G.area_name(a), text=text, t_min=round(n * SC.STEP_S / 60.0, 2)))
                spent += len(targets)
            if degraded:
                if spent:
                    self.msg_budget_next[a] = self.step_i + 9
            else:
                self.msg_credits[a] = min(float(MSG_BANK), self.msg_credits[a] - spent + MSG_REFILL)
        return self.msg_queue.pop(self.step_i, [[] for _ in range(G.N_AREAS)])
